-- ServiceNow start option, dev data (Plan B Task 8): the three ServiceNow code components
-- ("get new job" as a Start option, "complete job", "hand back"), the Okta playbook without its
-- "Complete ServiceNow Job" step, a "test" playbook, robot copies of both (published), and
-- workflow 62 rewired: Start (ServiceNow: New Job) -> Playbook from the job -> complete job | hand back.
-- Also deletes the Outlook leftover schedule (scheduled_workflows 15).
-- Dev instance only: the ids are this database's (user 3, robot 120, workflow 62, playbook 21).
-- Runs against the CONTEXTS database (netfo587_chatbot), where workflows live. One transaction;
-- on an error before COMMIT, run ROLLBACK.
START TRANSACTION;

-- 1. Code components
INSERT INTO code_components (user_id, name, description, code, exits, mcp_servers, timeout_s, created_at, updated_at) VALUES (3, 'ServiceNow: get new job', 'Claims the oldest open SynergyAI task; its tag names the playbook.', 'def run(input, call_tool):\n    # 1. Oldest open, unclaimed task in the SynergyAI group.\n    try:\n        job = call_tool(\"servicenow\", \"poll_jobs\", {}).get(\"job\")\n    except Exception as e:\n        return {\"route\": \"error\", \"output\": f\"poll_jobs: {e}\"}\n    if job is None:\n        return {\"route\": \"no_job\", \"output\": None}\n\n    # 2. Claim it before acting, so a second run can\'t take the same task.\n    #    Someone took or closed it in between: stop quietly. Anything else is an error.\n    try:\n        call_tool(\"servicenow\", \"claim_job\", {\"task\": job[\"task\"]})\n    except Exception as e:\n        if error_code(e) == \"not_claimable\":\n            return {\"route\": \"no_job\", \"output\": f\"{job[\'number\']} not claimable: {e}\"}\n        return {\"route\": \"error\", \"output\": f\"{job[\'number\']}: {e}\"}\n\n    # 3. Hand the job to the Playbook node: the tag names the playbook\n    #    (synergyai:okta-reset -> playbook \"okta-reset\"), the answers are its inputs.\n    tag = job.get(\"tag\") or \"\"\n    return {\"route\": \"job\", \"output\": {\n        \"task\": job[\"task\"],\n        \"number\": job[\"number\"],\n        \"playbook\": tag[len(\"synergyai:\"):] if tag.startswith(\"synergyai:\") else tag,\n        \"requested_for\": job[\"requested_for\"],\n        \"answers\": {k: v[\"value\"] for k, v in job[\"answers\"].items()},\n    }}\n\n\ndef error_code(e):\n    \"\"\"\'servicenow.claim_job: not_claimable: ...\' -> \'not_claimable\'.\"\"\"\n    rest = str(e).split(\": \", 1)[-1]\n    return rest.split(\":\", 1)[0].strip()', '[\"job\",\"no_job\",\"error\"]', '[\"ServiceNow\"]', 30, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
SET @c_get = LAST_INSERT_ID();
INSERT INTO code_components (user_id, name, description, code, exits, mcp_servers, timeout_s, created_at, updated_at) VALUES (3, 'ServiceNow: complete job', 'Closes the job the playbook finished (reads its Job: line).', 'import json\nimport re\n\n\ndef run(input, call_tool):\n    job = job_of(input)\n    if job is None:\n        return {\"route\": \"error\", \"output\": \"no Job: line in the playbook\'s output\"}\n    name = job.get(\"number\") or job[\"task\"]\n    try:\n        call_tool(\"servicenow\", \"complete_job\", {\"task\": job[\"task\"], \"notes\": summary_of(input)})\n    except Exception as e:\n        # the playbook handed the task back itself, or someone else took it\n        if error_code(e) in (\"task_not_found\", \"not_claimed\"):\n            return {\"route\": \"already_handed_back\", \"output\": f\"{name}: {e}\"}\n        return {\"route\": \"error\", \"output\": f\"{name}: {e}\"}\n    return {\"route\": \"closed\", \"output\": f\"{name} closed by SynergyAI.\"}\n\n\ndef summary_of(text):\n    \"\"\"The playbook\'s resolve summary (its ## Result section), else the transcript\'s last line; <= 4000 chars.\"\"\"\n    text = str(text or \"\")\n    m = re.search(r\"## Result\\n(.*?)(?:\\n\\n\\[playbook run |\\n\\nJob: |\\Z)\", text, re.S)\n    summary = m.group(1).strip() if m else \"\"\n    if not summary:\n        lines = [l.strip() for l in text.splitlines() if l.strip() and not l.startswith(\"Job: \")]\n        summary = lines[-1] if lines else \"Completed by SynergyAI.\"\n    return summary[:4000]\n\n\ndef job_of(text):\n    \"\"\"The job the Playbook node ran for: the last \"Job: {...}\" line of its output.\"\"\"\n    for line in reversed(str(text or \"\").splitlines()):\n        if line.startswith(\"Job: \"):\n            try:\n                job = json.loads(line[5:])\n            except ValueError:\n                return None\n            return job if isinstance(job, dict) and job.get(\"task\") else None\n    return None\n\n\ndef error_code(e):\n    \"\"\"\'servicenow.complete_job: not_claimed: ...\' -> \'not_claimed\'.\"\"\"\n    rest = str(e).split(\": \", 1)[-1]\n    return rest.split(\":\", 1)[0].strip()', '[\"closed\",\"already_handed_back\",\"error\"]', '[\"ServiceNow\"]', 30, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
SET @c_complete = LAST_INSERT_ID();
INSERT INTO code_components (user_id, name, description, code, exits, mcp_servers, timeout_s, created_at, updated_at) VALUES (3, 'ServiceNow: hand back', 'Gives the job back to a human group with the playbook\'s failure reason.', 'import json\n\nHUMAN_GROUP = \"Service Desk\"   # the group a job goes back to when the playbook did not finish\n\n\ndef run(input, call_tool):\n    job = job_of(input)\n    if job is None:\n        return {\"route\": \"error\", \"output\": \"no Job: line in the playbook\'s output\"}\n    name = job.get(\"number\") or job[\"task\"]\n    reason = (\"SynergyAI could not finish: \" + reason_of(input))[:4000]\n    try:\n        call_tool(\"servicenow\", \"hand_back\", {\"task\": job[\"task\"], \"group\": HUMAN_GROUP, \"reason\": reason})\n    except Exception as e:\n        # no longer a SynergyAI task: the playbook (or someone) already handed it back\n        if error_code(e) == \"task_not_found\":\n            return {\"route\": \"handed_back\", \"output\": f\"{name} was already handed back: {e}\"}\n        return {\"route\": \"error\", \"output\": f\"{name}: {e}\"}\n    return {\"route\": \"handed_back\", \"output\": f\"{name} handed back to {HUMAN_GROUP}: {reason}\"}\n\n\ndef reason_of(text):\n    \"\"\"The reason on the \"Playbook failed: <reason>\" line.\"\"\"\n    for line in str(text or \"\").splitlines():\n        if line.startswith(\"Playbook failed: \"):\n            return line[len(\"Playbook failed: \"):].strip()\n    return \"the playbook did not finish\"\n\n\ndef job_of(text):\n    \"\"\"The job the Playbook node ran for: the last \"Job: {...}\" line of its output.\"\"\"\n    for line in reversed(str(text or \"\").splitlines()):\n        if line.startswith(\"Job: \"):\n            try:\n                job = json.loads(line[5:])\n            except ValueError:\n                return None\n            return job if isinstance(job, dict) and job.get(\"task\") else None\n    return None\n\n\ndef error_code(e):\n    \"\"\"\'servicenow.complete_job: not_claimed: ...\' -> \'not_claimed\'.\"\"\"\n    rest = str(e).split(\": \", 1)[-1]\n    return rest.split(\":\", 1)[0].strip()', '[\"handed_back\",\"error\"]', '[\"ServiceNow\"]', 30, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
SET @c_hand = LAST_INSERT_ID();
UPDATE code_components SET start_trigger = '{\"label\":\"ServiceNow: New Job\",\"watch\":{\"server\":\"ServiceNow\",\"tool\":\"wait_for_jobs\",\"args\":{}},\"work_exit\":\"job\"}', updated_at = CURRENT_TIMESTAMP WHERE id = @c_get AND user_id = 3;

-- 2. Playbooks: Okta without "Complete ServiceNow Job"; new "test"; robot copies of both
UPDATE playbooks SET title = 'Okta password reset (ServiceNow request)', text = 'Title: Okta password reset (ServiceNow request)\nTrigger: A claimed ServiceNow task tagged synergyai:okta-reset. The input is the job record from the code node: task, number, requested_for and answers (email, reason).\nInstructions:\n1. Read the job record you received. Use its \"task\" value whenever a ServiceNow action needs the task, and the email from \"answers\".\n2. #Add ServiceNow Note to the task: \"SynergyAI started the Okta password reset for <email>.\"\n3. #Search Okta Users with that email.\n- If no user is found, #Hand Back ServiceNow Job to the group \"Service Desk\" with the reason \"No Okta account for <email>\", and stop.\n4. #Reset Okta Password for the user\'s id, with send_email true, so the user receives the reset link.\n- If the reset fails, #Hand Back ServiceNow Job to the group \"Identity Team\" with the reason and the error, and stop.\n5. #Add ServiceNow Note to the task: \"Okta password reset sent to <email>.\"\n6. Resolve the request with a one-line summary: the ServiceNow number, the email and the outcome (completed or handed back).\nTools used: Okta; ServiceNow\nActions used: #Add ServiceNow Note; #Search Okta Users; #Reset Okta Password; #Hand Back ServiceNow Job', updated_at = CURRENT_TIMESTAMP WHERE id = 21 AND user_id = 3;
INSERT INTO playbooks (user_id, pkey, title, text, created_at, updated_at) VALUES (3, 'test', 'SynergyAI test', 'Title: SynergyAI test\nTrigger: A claimed ServiceNow task tagged synergyai:test. The input is the job record from the code node: task, number, requested_for and answers.\nInstructions:\n1. Read the job record you received. Use its \"task\" value whenever a ServiceNow action needs the task.\n2. #Add ServiceNow Note to the task: \"SynergyAI test ran.\"\n3. Resolve the request with a one-line summary: the ServiceNow number and \"SynergyAI test ran\".\nTools used: ServiceNow\nActions used: #Add ServiceNow Note', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
SET @p_test = LAST_INSERT_ID();
INSERT INTO playbooks (user_id, pkey, title, text, created_at, updated_at, published_by, published_at, source_id) VALUES (120, 'okta-password-reset-servicenow-request', 'Okta password reset (ServiceNow request)', 'Title: Okta password reset (ServiceNow request)\nTrigger: A claimed ServiceNow task tagged synergyai:okta-reset. The input is the job record from the code node: task, number, requested_for and answers (email, reason).\nInstructions:\n1. Read the job record you received. Use its \"task\" value whenever a ServiceNow action needs the task, and the email from \"answers\".\n2. #Add ServiceNow Note to the task: \"SynergyAI started the Okta password reset for <email>.\"\n3. #Search Okta Users with that email.\n- If no user is found, #Hand Back ServiceNow Job to the group \"Service Desk\" with the reason \"No Okta account for <email>\", and stop.\n4. #Reset Okta Password for the user\'s id, with send_email true, so the user receives the reset link.\n- If the reset fails, #Hand Back ServiceNow Job to the group \"Identity Team\" with the reason and the error, and stop.\n5. #Add ServiceNow Note to the task: \"Okta password reset sent to <email>.\"\n6. Resolve the request with a one-line summary: the ServiceNow number, the email and the outcome (completed or handed back).\nTools used: Okta; ServiceNow\nActions used: #Add ServiceNow Note; #Search Okta Users; #Reset Okta Password; #Hand Back ServiceNow Job', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 3, CURRENT_TIMESTAMP, 21),
  (120, 'test', 'SynergyAI test', 'Title: SynergyAI test\nTrigger: A claimed ServiceNow task tagged synergyai:test. The input is the job record from the code node: task, number, requested_for and answers.\nInstructions:\n1. Read the job record you received. Use its \"task\" value whenever a ServiceNow action needs the task.\n2. #Add ServiceNow Note to the task: \"SynergyAI test ran.\"\n3. Resolve the request with a one-line summary: the ServiceNow number and \"SynergyAI test ran\".\nTools used: ServiceNow\nActions used: #Add ServiceNow Note', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 3, CURRENT_TIMESTAMP, @p_test);

-- 3. Workflow 62: Start on "ServiceNow: get new job" -> Playbook from the job -> complete job | hand back
DELETE FROM workflow_edges WHERE workflow_id = 62;
DELETE FROM workflow_nodes WHERE id = 2606 AND workflow_id = 62;
UPDATE workflow_nodes SET config = JSON_SET(config, '$.start_option', @c_get), pos_x = 10, pos_y = 400 WHERE id = 2605 AND workflow_id = 62;
UPDATE workflow_nodes SET config = '{\"name\":\"Playbook from the job\",\"type\":\"playbook\",\"model\":\"\",\"agent_id\":null,\"disabled\":false,\"node_type\":\"playbook\",\"agent_type\":null,\"mcp_servers\":[],\"playbook_id\":null,\"agent_provider\":\"claude\",\"writes_enabled\":true,\"playbook_source\":\"input\",\"playbook_input_field\":\"playbook\",\"exits\":[\"done\",\"failed\"]}', pos_x = 300, pos_y = 300 WHERE id = 2608 AND workflow_id = 62;
UPDATE workflow_nodes SET pos_x = 840, pos_y = 200 WHERE id = 2607 AND workflow_id = 62;
UPDATE workflow_nodes SET pos_x = 300, pos_y = 560 WHERE id = 2610 AND workflow_id = 62;
UPDATE workflow_nodes SET pos_x = 300, pos_y = 720 WHERE id = 2609 AND workflow_id = 62;
INSERT INTO workflow_nodes (workflow_id, node_type, agent_id, config, pos_x, pos_y, drawflow_node_id) VALUES (62, 'code', NULL, JSON_OBJECT('type', 'code', 'name', 'ServiceNow: complete job', 'code_component_id', @c_complete, 'disabled', CAST('false' AS JSON)), 560, 220, '18');
SET @n_complete = LAST_INSERT_ID();
INSERT INTO workflow_nodes (workflow_id, node_type, agent_id, config, pos_x, pos_y, drawflow_node_id) VALUES (62, 'code', NULL, JSON_OBJECT('type', 'code', 'name', 'ServiceNow: hand back', 'code_component_id', @c_hand, 'disabled', CAST('false' AS JSON)), 560, 420, '19');
SET @n_hand = LAST_INSERT_ID();
INSERT INTO workflow_nodes (workflow_id, node_type, agent_id, config, pos_x, pos_y, drawflow_node_id) VALUES (62, 'output', NULL, '{"type":"output","disabled":false}', 840, 420, '20');
SET @n_out_back = LAST_INSERT_ID();
INSERT INTO workflow_edges (workflow_id, from_node_id, to_node_id, from_port, to_port) VALUES
  (62, 2605, 2608, 'output_1', 'input_1'),          -- job
  (62, 2605, 2610, 'output_2', 'input_1'),          -- no_job
  (62, 2605, 2609, 'output_3', 'input_1'),          -- error
  (62, 2608, @n_complete, 'output_1', 'input_1'),   -- done
  (62, 2608, @n_hand, 'output_2', 'input_1'),       -- failed
  (62, @n_complete, 2607, 'output_1', 'input_1'),   -- closed
