-- 4. The Outlook leftover schedule on workflow 62
DELETE FROM scheduled_workflows WHERE id = 15 AND workflow_id = 62;
UPDATE agent_workflows SET updated_at = CURRENT_TIMESTAMP WHERE id = 62;

COMMIT;
